  "description": "Explains the signals related to attempting to artificially create price momentum.",
  "definition": "The momentum ignition signal indicates attempts to create false price movement. 'Strong' suggests clear patterns of manipulative intent; 'Weak' suggests such patterns are less evident."
}

{
  "id": 1,
  "knowledge": "Order Modification Intensity (OMI)",
  "description": "Measures how frequently a trader modifies orders relative to their cancellation rate.",
  "definition": "OMI = \\frac{\\text{Order Modification Frequency}}{1 - \\text{Order Cancellation Percentage}} \\text{ (undefined if cancellation percentage is 1)}"
}

{
  "id": 36,
  "knowledge": "Aggressive Trading Intensity (ATI)",
  "description": "Measures intensity by combining high turnover, leverage, and order modification frequency.",
  "definition": "ATI = 'Daily Turnover Rate' \\times 'Trader Leverage Exposure' \\times 'Order Modification Intensity'."
}

{
  "id": 31,
  "knowledge": "Combined Manipulation Indicator (CMI)",
  "description": "A combined score reflecting both general suspicious activity and specific pattern anomalies.",
  "definition": "CMI = ('Suspicious Activity Index' + 'Pattern Anomaly Score') / 2"
}

{
  "id": 3,
  "knowledge": "Suspicious Activity Index (SAI)",
  "description": "A composite index attempting to quantify overall suspicious trading behavior based on risk indicators.",
  "definition": "SAI is a weighted sum of normalized risk indicators, including probabilities for spoofing, front-running, wash trading, and confirmed layering."
}

{
  "id": 4,
  "knowledge": "Pattern Anomaly Score (PAS)",
  "description": "Measures the deviation of a trader's pattern similarity from their peer correlation, potentially indicating unique illicit behavior.",
  "definition": "PAS = |\\text{Pattern Similarity Score} - \\text{Peer Correlation Score}|"
}

